ts_message("chunk #42 `<gt_curves_bootstrap>` start")

num_block_boots <- 250

blocks <- create_blocks(gen0, chrom, pos, 15000, block_by = "snp", sep = "_")

num_blocks <- length(unique(blocks$window))

output_gt_kmate_blocks <- paste(
  "/global/scratch/users/milesroberts/moi_lab_projects/grenenet-phase2/results/",
  today,
  "/gt_boots_kmate.tsv",
  sep = ""
)

output_var_cov_blocks <- paste(
  "/global/scratch/users/milesroberts/moi_lab_projects/grenenet-phase2/results/",
  today,
  "/var_cov_boots_kmate.tsv",
  sep = ""
)

# delete previous run
check_file_exists(output_gt_kmate_blocks)
check_file_exists(output_var_cov_blocks)

# check that directory exists
folder_path <- dirname(output_gt_kmate_blocks)
if (!dir.exists(folder_path)) {
  dir.create(folder_path, recursive = TRUE, showWarnings = FALSE)
}

# make list of sites
# for now, ignore some sites
sites <- unique(gsub("_.*", "", colnames(hapfire)))
  
for (site in unique(sites)) {
  print(paste(Sys.time(), "- Site:", site))
  hap_site <- hapfire %>% 
    dplyr::select(starts_with(paste(site, "_", sep = "")))
  
  for (exprep in 1:12) {
    print(paste(Sys.time(), "- Rep:", exprep))
    hap_rep <- hap_site %>%
      dplyr::select(ends_with(paste("_", exprep, sep = ""))) %>%
      collect() %>%
      mutate(window = blocks$window) # add block ids
      #filter(row_number() %in% cls_idx) # subset to variant class
    
    # sort names to be in order of generation
    hap_rep <- hap_rep %>%
      relocate(all_of(sort(colnames(hap_rep))))
    
    if (ncol(hap_rep) < 2) {
      print("Need at least two increments. Skipping to next replicate...")
      next
    }
    
    rep_n <- grab_sample_sizes(flower_counts, pool, colnames(hap_rep), 10000, total_flowers)
    
    hap_rep <- cbind(gen0$X0_0_0, hap_rep)
    colnames(hap_rep)[1] = paste(site, "_0_", exprep, sep = "")
    
    for(b in 1:num_block_boots){
      
      if(b %% 25 == 0){
        print(paste(Sys.time(), "- Bootstraps done:", b))
      }
      
      hap_boot <- hap_rep %>%
        nest(data = -window) %>% 
        slice_sample(n = num_blocks, replace = TRUE) %>% 
        #mutate(new_group_id = row_number()) %>% 
        unnest(cols = c(data))  %>%
        select(-window) %>% 
        as.data.frame()
      
      covmat <- covmat_from_pmat(
        hap_boot,
        rep_n$total_flowers*2,
        correct_for_n = T,
        input_asin_trans = F,
        standard_by_het = F
      )
      
      # save raw var-cov matrix
      covlong <- covmat %>%
        as.data.frame() %>%
        rownames_to_column(var = "A") %>%
        pivot_longer(cols = -A, names_to = "B", values_to = "cov")
      
      covlong$site <- site
      covlong$rep <- exprep
      covlong$class = "smallindel_sv_snp" #paste(cls, collapse = "_")
      covlong$boot = b
      covlong$weight = nrow(hap_boot)
      append_table(covlong, output_var_cov_blocks)
      
      gt_result <- gt_from_covmat(covmat)
      gt_result$site = site
      gt_result$rep = exprep
      gt_result$boot = b
      gt_result$class = "smallindel_sv_snp" #paste(cls, collapse = "_")
      gt_result$weight = nrow(hap_boot)
      append_table(gt_result, output_gt_kmate_blocks)
      
      rm(gt_result, hap_boot); gc()
    }
    rm(hap_rep); gc()
  }
  rm(hap_site); gc()
}
